using CommissionCalculator.Engine;

namespace Adv;

public static class H
{
    public static DateOnly D(string s) => DateOnly.Parse(s);
    public static QuarterPeriod Q(string a, string b) => new(D(a), D(b));

    public static RepInput Rep(string id, decimal quota, string start, decimal opening = 0m)
        => new(id, id, quota, D(start), opening);

    public static SplitCredit S(string id, decimal pct) => new(id, pct);
    public static RefundInput Rf(decimal amt, string date) => new(amt, D(date));

    public static DealInput Deal(string id, decimal amount, string close, string book,
        SplitCredit[] splits, RefundInput[]? refunds = null)
        => new(id, amount, D(close), D(book), splits, refunds ?? Array.Empty<RefundInput>());

    public static DealInput Solo(string id, decimal amount, string close, string book, string rep,
        RefundInput[]? refunds = null)
        => Deal(id, amount, close, book, new[] { S(rep, 100m) }, refunds);

    public static BookingQuarterInput BQ(string a, string b, BookingQuarterRep[] reps,
        Partner[] partners, DealInput[] deals) => new(Q(a, b), reps, partners, deals);

    public static BookingQuarterRep BRep(string id, decimal quota, string start)
        => new(id, quota, D(start));

    public static ScenarioInput Sc(string id, string qa, string qb, RepInput[] roster,
        DealInput[] deals, BookingQuarterInput[]? bqs = null)
        => new(id, id, Q(qa, qb), roster, deals, bqs ?? Array.Empty<BookingQuarterInput>());

    public static void Run(string label, ScenarioInput sc)
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("### " + label);
        var r = CommissionEngine.Calculate(sc);
        switch (r)
        {
            case RejectedScenario rej:
                Console.WriteLine("REJECTED:");
                foreach (var e in rej.Errors) Console.WriteLine($"  [{e.RequirementId}] {e.Message}");
                break;
            case CalculatedScenario c:
                foreach (var st in c.Statements)
                {
                    Console.WriteLine($"-- {st.RepId}: quota={st.Quota} prorated={st.ProratedQuota} booked={st.CreditedBookings} attain={st.Attainment} before={st.CommissionBeforeRefunds} claw={st.Clawbacks} earned={st.EarnedCommission} draw={st.DrawPaid} rec={st.Recovered} pay={st.Payable} close={st.ClosingRecoverableBalance}");
                    foreach (var l in st.Lines)
                        Console.WriteLine($"     {l.Section,-9} {l.Amount,15} {l.RequirementId,-7} {l.Description}");
                }
                break;
        }
        Console.WriteLine();
    }
}

