using System.Globalization;
using System.Text.Json;
using System.Text.Json.Serialization;
using CommissionCalculator.Engine;

namespace Adv;

public sealed class JRep
{
    public string RepId { get; set; } = "";
    public string Quota { get; set; } = "0";
    public string Start { get; set; } = "2020-01-01";
    public string Opening { get; set; } = "0";
}

public sealed class JPartner
{
    public string RepId { get; set; } = "";
    public string Start { get; set; } = "2020-01-01";
}

public sealed class JDeal
{
    public string DealId { get; set; } = "";
    public string Amount { get; set; } = "0";
    public string Close { get; set; } = "2020-01-01";
    public string Book { get; set; } = "2020-01-01";
    public List<List<string>> Splits { get; set; } = new();
    public List<List<string>> Refunds { get; set; } = new();
}

public sealed class JBookingQuarter
{
    public List<string> Quarter { get; set; } = new();
    public List<JRep> Reps { get; set; } = new();
    public List<JPartner> Partners { get; set; } = new();
    public List<JDeal> Deals { get; set; } = new();
}

public sealed class JScenario
{
    public string Id { get; set; } = "";
    public string Note { get; set; } = "";
    public List<string> Quarter { get; set; } = new();
    public List<JRep> Roster { get; set; } = new();
    public List<JDeal> Deals { get; set; } = new();
    public List<JBookingQuarter> BookingQuarters { get; set; } = new();
}

public static class Program
{
    static readonly JsonSerializerOptions Opts = new()
    {
        PropertyNameCaseInsensitive = true,
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.Never,
    };

    static DateOnly D(string s) => DateOnly.ParseExact(s, "yyyy-MM-dd", CultureInfo.InvariantCulture);
    static decimal M(string s) => decimal.Parse(s, CultureInfo.InvariantCulture);

    static DealInput ToDeal(JDeal d) => new(
        d.DealId, M(d.Amount), D(d.Close), D(d.Book),
        d.Splits.Select(s => new SplitCredit(s[0], M(s[1]))).ToList(),
        d.Refunds.Select(r => new RefundInput(M(r[0]), D(r[1]))).ToList());

    public static int Main(string[] args)
    {
        var inPath = args[0];
        var outPath = args[1];
        var scenarios = JsonSerializer.Deserialize<List<JScenario>>(File.ReadAllText(inPath), Opts)!;
        var results = new List<object>();

        foreach (var js in scenarios)
        {
            var sc = new ScenarioInput(js.Id, js.Id,
                new QuarterPeriod(D(js.Quarter[0]), D(js.Quarter[1])),
                js.Roster.Select(r => new RepInput(r.RepId, r.RepId, M(r.Quota), D(r.Start), M(r.Opening))).ToList(),
                js.Deals.Select(ToDeal).ToList(),
                js.BookingQuarters.Select(b => new BookingQuarterInput(
                    new QuarterPeriod(D(b.Quarter[0]), D(b.Quarter[1])),
                    b.Reps.Select(r => new BookingQuarterRep(r.RepId, M(r.Quota), D(r.Start))).ToList(),
                    b.Partners.Select(p => new Partner(p.RepId, D(p.Start))).ToList(),
                    b.Deals.Select(ToDeal).ToList())).ToList());

            object entry;
            try
            {
                var res = CommissionEngine.Calculate(sc);
                entry = res switch
                {
                    RejectedScenario rej => new
                    {
                        id = js.Id,
                        status = "rejected",
                        errors = rej.Errors.Select(e => new { fr = e.RequirementId, msg = e.Message }).ToList(),
                        statements = (object?)null,
                    },
                    CalculatedScenario c => new
                    {
                        id = js.Id,
                        status = "ok",
                        errors = (object?)null,
                        statements = c.Statements.Select(s => new
                        {
                            repId = s.RepId,
                            quota = s.Quota.ToString(CultureInfo.InvariantCulture),
                            proratedQuota = s.ProratedQuota.ToString(CultureInfo.InvariantCulture),
                            creditedBookings = s.CreditedBookings.ToString(CultureInfo.InvariantCulture),
                            attainment = s.Attainment.ToString(CultureInfo.InvariantCulture),
                            commissionBeforeRefunds = s.CommissionBeforeRefunds.ToString(CultureInfo.InvariantCulture),
                            clawbacks = s.Clawbacks.ToString(CultureInfo.InvariantCulture),
                            earned = s.EarnedCommission.ToString(CultureInfo.InvariantCulture),
                            drawPaid = s.DrawPaid.ToString(CultureInfo.InvariantCulture),
                            recovered = s.Recovered.ToString(CultureInfo.InvariantCulture),
                            payable = s.Payable.ToString(CultureInfo.InvariantCulture),
                            closing = s.ClosingRecoverableBalance.ToString(CultureInfo.InvariantCulture),
                            lines = s.Lines.Select(l => new
                            {
                                section = l.Section.ToString(),
                                amount = l.Amount.ToString(CultureInfo.InvariantCulture),
                                fr = l.RequirementId,
                                desc = l.Description,
                            }).ToList(),
                        }).ToList(),
                    },
                    _ => throw new InvalidOperationException("unknown result"),
                };
            }
            catch (Exception ex)
            {
                entry = new { id = js.Id, status = "threw", errors = (object?)null, statements = (object?)null, exception = ex.GetType().Name + ": " + ex.Message };
            }

            results.Add(entry);
        }

        File.WriteAllText(outPath, JsonSerializer.Serialize(results, Opts));
        Console.WriteLine($"wrote {results.Count} results to {outPath}");
        return 0;
    }
}

