import json
import random
import sys
from datetime import date, timedelta

HERE = "<scratch>/scratchpad/adversarial"

QUARTERS = [
    (date(2026, 1, 1), date(2026, 3, 31), date(2025, 10, 1), date(2025, 12, 31)),
    (date(2026, 4, 1), date(2026, 6, 30), date(2026, 1, 1), date(2026, 3, 31)),
    (date(2026, 7, 1), date(2026, 9, 30), date(2026, 4, 1), date(2026, 6, 30)),
    (date(2024, 1, 1), date(2024, 3, 31), date(2023, 10, 1), date(2023, 12, 31)),  # leap
    (date(2024, 4, 1), date(2024, 6, 30), date(2024, 1, 1), date(2024, 3, 31)),
]


def money(rng, lo, hi):
    return f"{rng.randint(lo, hi) / 100:.2f}"


def rand_pcts(rng, n):
    """n percentages, each > 0, <= 100, summing to exactly 100, with up to 3 decimals."""
    units = 100000
    cuts = sorted(rng.sample(range(1, units), n - 1)) if n > 1 else []
    parts = []
    prev = 0
    for c in cuts + [units]:
        parts.append(c - prev)
        prev = c
    if any(p <= 0 for p in parts):
        return None
    return [f"{p / 1000:.3f}" for p in parts]


def make(rng, idx):
    qs, qe, bs, be = rng.choice(QUARTERS)
    nreps = rng.randint(1, 4)
    roster = []
    for i in range(nreps):
        mid = rng.random() < 0.35
        if mid:
            start = qs + timedelta(days=rng.randint(1, (qe - qs).days))
        else:
            start = qs - timedelta(days=rng.randint(0, 600))
        roster.append({
            "repId": f"r{i}",
            "quota": money(rng, 100_00, 30_000_00) if rng.random() < 0.5 else money(rng, 1_000_00, 500_000_00),
            "start": start.isoformat(),
            "opening": "0" if rng.random() < 0.5 else money(rng, 0, 20_000_00),
        })

    def eligible(on_or_after):
        return [r for r in roster if date.fromisoformat(r["start"]) <= on_or_after]

    deals = []
    for k in range(rng.randint(0, 6)):
        # booking date: mostly inside the quarter, sometimes outside (excluded, no refunds)
        inside = rng.random() < 0.8
        if inside:
            book = qs + timedelta(days=rng.randint(0, (qe - qs).days))
        else:
            book = qs - timedelta(days=rng.randint(1, 200)) if rng.random() < 0.5 \
                else qe + timedelta(days=rng.randint(1, 60))
        elig = eligible(book)
        if not elig:
            continue
        n = min(len(elig), rng.choice([1, 1, 2, 2, 3, 4]))
        picked = rng.sample(elig, n)
        pcts = rand_pcts(rng, n)
        if pcts is None:
            continue
        amt_cents = rng.choice([rng.randint(1, 20), rng.randint(1, 10000),
                                rng.randint(1, 30_000_00), rng.randint(1, 500_000_00)])
        close = book - timedelta(days=rng.randint(0, 10))
        refunds = []
        if inside and rng.random() < 0.5:
            left = amt_cents
            for _ in range(rng.randint(1, 3)):
                if left <= 0:
                    break
                r = rng.randint(1, left)
                left -= r
                rd = book + timedelta(days=rng.randint(0, 200))
                refunds.append([f"{r / 100:.2f}", rd.isoformat()])
        deals.append({
            "dealId": f"D{k}",
            "amount": f"{amt_cents / 100:.2f}",
            "close": close.isoformat(),
            "book": book.isoformat(),
            "splits": [[picked[i]["repId"], pcts[i]] for i in range(n)],
            "refunds": refunds,
        })

    # booking quarter: only reps whose start is on/before its first day
    bq_reps = [r for r in roster if date.fromisoformat(r["start"]) <= bs]
    bqs = []
    if bq_reps and rng.random() < 0.7:
        partner = {"repId": "pz", "start": (bs - timedelta(days=400)).isoformat()}
        bdeals = []
        for k in range(rng.randint(1, 4)):
            book = bs + timedelta(days=rng.randint(0, (be - bs).days))
            cands = bq_reps + ([partner] if rng.random() < 0.4 else [])
            n = min(len(cands), rng.choice([1, 1, 2, 3]))
            picked = rng.sample(cands, n)
            pcts = rand_pcts(rng, n)
            if pcts is None:
                continue
            amt_cents = rng.choice([rng.randint(1, 20), rng.randint(1, 10000),
                                    rng.randint(1, 500_000_00)])
            refunds = []
            left = amt_cents
            for _ in range(rng.randint(1, 3)):
                if left <= 0:
                    break
                r = rng.randint(1, left)
                left -= r
                # dates spread across the booking quarter, the gap, and this quarter
                rd = book + timedelta(days=rng.randint(0, 330))
                refunds.append([f"{r / 100:.2f}", rd.isoformat()])
            bdeals.append({
                "dealId": f"B{k}",
                "amount": f"{amt_cents / 100:.2f}",
                "close": (book - timedelta(days=rng.randint(0, 5))).isoformat(),
                "book": book.isoformat(),
                "splits": [[picked[i]["repId"], pcts[i]] for i in range(n)],
                "refunds": refunds,
            })
        if bdeals:
            credited = {s[0] for d in bdeals for s in d["splits"]}
            bqs.append({
                "quarter": [bs.isoformat(), be.isoformat()],
                "reps": [{"repId": r["repId"], "quota": money(rng, 1_000_00, 300_000_00),
                          "start": r["start"]}
                         for r in bq_reps if r["repId"] in credited],
                "partners": [partner] if partner["repId"] in credited else [],
                "deals": bdeals,
            })

    return {"id": f"f{idx}", "note": "", "quarter": [qs.isoformat(), qe.isoformat()],
            "roster": roster, "deals": deals, "bookingQuarters": bqs}


def main(seed, n):
    rng = random.Random(seed)
    out = [make(rng, i) for i in range(n)]
    with open(f"{HERE}/fuzz.scenarios.json", "w") as f:
        json.dump(out, f, indent=1)
    print("ok", len(out))


if __name__ == "__main__":
    main(int(sys.argv[1]), int(sys.argv[2]))

