from decimal import Decimal, ROUND_HALF_UP
def r2(x): return Decimal(x).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)
def comm(bk, q, rounded_edge):
    edge = r2(q*Decimal('1.5')) if rounded_edge else q*Decimal('1.5')
    t=Decimal(0); lines=[]
    b1=min(bk,q)
    if b1>0: a=r2(b1*Decimal('0.05')); t+=a; lines.append(('5%',b1,a))
    if bk>q:
        b2=min(bk,edge)-q
        if b2>0: a=r2(b2*Decimal('0.08')); t+=a; lines.append(('8%',b2,a))
    if bk>edge:
        b3=bk-edge
        if b3>0: a=r2(b3*Decimal('0.12')); t+=a; lines.append(('12%',b3,a))
    return t, lines
